class Solution {
public:
    vector<long long> maximumSegmentSum(vector<int>& nums, vector<int>& removeQueries) {
        int n = nums.size();
        vector<int> par(n);
        vector<long long> segSum(n, 0);
        vector<int> sz(n, 0); // sz > 0 means active
        for (int i = 0; i < n; ++i) par[i] = i;

        multiset<long long> ms;
        vector<long long> ans(n);
        ans[n - 1] = 0;

        auto find = [&](int x) {
            while (par[x] != x) {
                par[x] = par[par[x]];
                x = par[x];
            }
            return x;
        };

        for (int i = n - 1; i >= 1; --i) {
            int j = removeQueries[i];
            par[j] = j;
            segSum[j] = nums[j];
            sz[j] = 1;
            ms.insert(segSum[j]);

            if (j > 0 && sz[j - 1] > 0) {
                int a = find(j - 1), b = find(j);
                ms.erase(ms.find(segSum[a]));
                ms.erase(ms.find(segSum[b]));
                par[b] = a;
                segSum[a] += segSum[b];
                sz[a] += sz[b];
                ms.insert(segSum[a]);
            }
            if (j < n - 1 && sz[j + 1] > 0) {
                int a = find(j + 1), b = find(j);
                ms.erase(ms.find(segSum[a]));
                ms.erase(ms.find(segSum[b]));
                par[b] = a;
                segSum[a] += segSum[b];
                sz[a] += sz[b];
                ms.insert(segSum[a]);
            }

            ans[i - 1] = ms.empty() ? 0 : *ms.rbegin();
        }
        return ans;
    }
};
